fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    let m = x.len();
    assert!(m > 0, "matrix must be non-empty");

    let n = x[0].len();
    assert!(n > 0, "rows must be non-empty");

    // Ensure rectangular matrix (all rows same length).
    for row in &x {
        assert!(row.len() == n, "matrix must be rectangular");
    }

    // result has n rows and each row has length m
    let mut result = vec![vec![0.0f32; m]; n];
    for r in 0..m {
        for c in 0..n {
            result[c][r] = x[r][c];
        }
    }
    result
}